use std::sync::{Arc, Condvar, Mutex};
use std::thread;

struct Channel {
    slot: Mutex<Option<i32>>,
    not_empty: Condvar,
    not_full: Condvar,
}

impl Channel {
    fn new() -> Self {
        Channel {
            slot: Mutex::new(None),
            not_empty: Condvar::new(),
            not_full: Condvar::new(),
        }
    }

    fn send(&self, value: i32) {
        let mut slot = self.slot.lock().unwrap();
        while slot.is_some() {
            slot = self.not_full.wait(slot).unwrap();
        }
        *slot = Some(value);
        self.not_empty.notify_one();
    }

    fn recv(&self) -> i32 {
        let mut slot = self.slot.lock().unwrap();
        while slot.is_none() {
            slot = self.not_empty.wait(slot).unwrap();
        }
        let value = slot.take().unwrap();
        self.not_full.notify_one();
        value
    }
}

fn sender(m: Arc<Mutex<()>>, ch: Arc<Channel>) {
    let _ = m.lock().unwrap();
    ch.send(1);

    let _ = m.lock().unwrap();
    ch.send(2);

    let _ = m.lock().unwrap();
}

fn receiver(m: Arc<Mutex<()>>, ch: Arc<Channel>) {
    let _v1 = ch.recv();

    let _ = m.lock().unwrap();
    let _v2 = ch.recv();

    let _ = m.lock().unwrap();
}

fn main() {
    let m = Arc::new(Mutex::new(()));
    let ch = Arc::new(Channel::new());

    let m_s = Arc::clone(&m);
    let ch_s = Arc::clone(&ch);
    let sender_handle = thread::spawn(move || sender(m_s, ch_s));

    let m_r = Arc::clone(&m);
    let ch_r = Arc::clone(&ch);
    let receiver_handle = thread::spawn(move || receiver(m_r, ch_r));

    sender_handle.join().unwrap();
    receiver_handle.join().unwrap();

    println!("DONE done=1");
}
